INSERT INTO public.content_items
    (id, content_group_id, content_type, content_text, is_active)
SELECT
    cs.id, cg.id, cs.content_type, cs.content_text, TRUE
FROM content_seed cs
JOIN public.topics t
  ON t.code = cs.topic_code
JOIN public.content_groups cg
  ON cg.topic_id = t.id
 AND cg.code = cs.group_code
ON CONFLICT (id) DO UPDATE
SET content_group_id = EXCLUDED.content_group_id,
    content_type = EXCLUDED.content_type,
    content_text = EXCLUDED.content_text,
    is_active = TRUE;

COMMIT;

-- Expected: 880 content_items; 440 Friends and 440 Family.
-- All source_id values were retained in this script for traceability;
-- source_id is not stored as an extra database column.
